import { formatdisplayDate } from "@/JsonFiles/DateFormate.js";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import SnackBar from "@/components/SnackBar.vue";
import { API, graphqlOperation } from "aws-amplify";
import { list_all_assets } from "@/graphql/queries.js";
import AdminAssetdetails from "@/components/Asset/Popups/AdminAssetdetails.vue";
export default {
  components: {
    SnackBar,
    AdminAssetdetails
  },
  mixins: [get_all_org_users],
  data() {
    return {
      SnackBarComponent: {},
      componentCheck: 0,
      tableLoading: false,
      adminassetItems: {},
      locationasset: false,
      assetstatus: "ACTIVE",
      searchF: "",
      adminassetHeaders: [{
        title: "Asset ID",
        value: "asset_prefix",
        sortable: false
      }, {
        title: "Category",
        value: "category_id_text",
        sortable: false
      }, {
        title: "Sub Category",
        value: "sub_category_id_text",
        sortable: false
      }, {
        title: "Product Serial No",
        value: "asset_product_serial_no",
        sortable: false
      }, {
        title: "Location",
        value: "asset_location",
        sortable: false
      }, {
        title: "Managed By",
        value: "asset_assined_to_name",
        sortable: false
      }, {
        title: "Verified On",
        value: "asset_verified_on",
        sortable: false
      }, {
        title: "Verified By",
        value: "asset_verified_by",
        sortable: false
      }, {
        title: "QR Tagged",
        value: "asset_tagged_status",
        sortable: false
      }],
      adminassetRecords: [],
      allUSersNames: [],
      currentPage: 1,
      itemsPerPage: 20,
      paginatedItems: [],
      windowHeight: 0,
      assetdisplay: false
    };
  },
  async created() {
    await this.fetch_assetsadmin();
  },
  mounted() {
    this.updateWindowHeight();
    window.addEventListener('resize', this.updateWindowHeight);
  },
  beforeDestroy() {
    window.removeEventListener('resize', this.updateWindowHeight);
  },
  computed: {
    totalCount() {
      return this.adminassetRecords.length;
    },
    pageCount() {
      return Math.ceil(this.adminassetRecords.length / this.itemsPerPage);
    },
    visiblePages() {
      const totalPages = this.pageCount;
      const current = this.currentPage;
      const delta = 2;
      let start = Math.max(1, current - delta);
      let end = Math.min(totalPages, current + delta);
      if (end - start < 4) {
        if (start === 1) {
          end = Math.min(totalPages, start + 4);
        } else {
          start = Math.max(1, end - 4);
        }
      }
      const pages = [];
      for (let i = start; i <= end; i++) {
        pages.push(i);
      }
      return pages;
    },
    windowHeight() {
      return window.innerHeight - 250; // Adjust height based on header and padding
    }
  },
  watch: {
    currentPage() {
      this.updatePageItems();
    }
  },
  methods: {
    fetch_user_name(value) {
      var name = "";
      this.allUSersNames.forEach(element => {
        if (element.user_email_id == value) {
          name = element.full_user_name;
        }
      });
      if (value == "SYSTEM") {
        name = value;
      }
      return name;
    },
    handle_row_click(click, val) {
      this.adminassetItems = val.item;
      this.componentCheck = 1;
      this.assetdisplay = true;
    },
    formate_date(value) {
      var data = formatdisplayDate(value);
      return data;
    },
    get_date(val) {
      const d = new Date(parseInt(val));
      var date = d.getDate().toLocaleString();
      var month = (d.getMonth() + 1).toLocaleString();
      var year = d.getFullYear();
      return (+date <= 9 ? "0" + date : date) + "/" + (+month <= 9 ? "0" + month : month) + "/" + year;
    },
    open_qrDailog(item) {
      // QR dialog functionality can be added here if needed
      console.log('QR dialog for item:', item);
    },
    async get_data() {
      this.adminassetRecords = [];
      await this.fetch_assetsadmin();
    },
    async clear_data() {
      this.adminassetRecords = [];
      await this.fetch_assetsadmin();
    },
    updateWindowHeight() {
      this.windowHeight = window.innerHeight - 250; // Adjust height based on header and padding
    },
    async fetch_assetsadmin() {
      this.tableLoading = true;
      var data = this.$store.getters.GetUserObj;
      try {
        let result = await API.graphql(graphqlOperation(list_all_assets, {
          input: {
            user_email_id: this.userselect == "ALL" ? undefined : this.userselect,
            organization_id: data.organization.organization_id,
            asset_shipment_status: "INTRANSIT"
            // asset_shipment_status:''
            //   asset_status:
            //     this.assetstatus == "ALL" ? undefined : this.assetstatus,
            //   asset_tagged_status:
            //     this.assettaggedstatus == "ALL"
            //       ? undefined
            //       : this.assettaggedstatus,
            //   sub_category_id: this.categoriessubName,
            //   category_id: this.categoriesName,
          }
        }));
        var response = JSON.parse(result.data.list_all_assets);
        this.adminassetRecords = [];
        this.tableLoading = false;
        if (response.Status == "SUCCESS") {
          this.adminassetRecords = response.data;
          this.tableLoading = false;
          this.updatePageItems();
        } else {
          this.adminassetRecords = [];
          this.tableLoading = false;
        }
      } catch (error) {
        this.adminassetRecords = [];
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    async updatePageItems() {
      const start = (this.currentPage - 1) * this.itemsPerPage;
      const end = start + this.itemsPerPage;
      this.paginatedItems = this.adminassetRecords.slice(start, end);
    }
  }
};
